INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16631$nota-0282$m16631$, $m16632$Exercise Physiology McArdle.pdf$m16632$, $m16633$735$m16633$, $m16634$The possibility of misclassifying someone as overweight (or obese) by applying BMI standards pertains particularly to large-size field athletes, bodybuilders, weightlifters, heavier wrestlers, and most professional American football players.$m16634$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16635$nota-0282$m16635$, $m16636$Exercise Physiology McArdle.pdf$m16636$, $m16637$736$m16637$, $m16638$racing cyclists who participated in the Tour de France—had remarkably low BMIs. In the 1997 race, the BMI for 170 competitors averaged 21.5 (1.79 m stature (70.5 in.), 68.7 kg (151.1 lb) body mass)... The results were almost identical in 2005 for the 189 riders... On average, the variation in stature and body weight among cycling teams remains remarkably small.$m16638$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16639$nota-0282$m16639$, $m16640$Exercise Physiology McArdle.pdf$m16640$, $m16641$736$m16641$, $m16642$The homogeneity in body size variables among these top-level performers makes it unlikely that body composition variables per se determine individual differences in cycling performance.$m16642$);
