INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m16647$nota-0282$m16647$, $m16648$nota-0164$m16648$, $m16649$complementa$m16649$, $m16650$mesma lógica de nota-0164 (uma métrica fisiológica isolada não determina desempenho): aqui aplicada a composição corporal/IMC entre ciclistas de elite homogêneos$m16650$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16651$nota-0283$m16651$, $m16652$Exercise Physiology McArdle.pdf$m16652$, $m16653$769$m16653$, $m16654$Figure 29.1 • Comparison of the lean-fat ratio among male and female competitors in diverse sports. Values are based on the average body mass and percentage body fat for each sport from various studies in the literature... Road cyclists, pro — Mass, kg 71.3; % Fat 11.6; FFM, kg 63.0$m16654$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16655$nota-0283$m16655$, $m16656$Exercise Physiology McArdle.pdf$m16656$, $m16657$769$m16657$, $m16658$Marathon runners — Mass, kg 59.4; % Fat 3.3; FFM, kg 57.4 ... Distance runners — Mass, kg 67.2; % Fat 11.8; FFM, kg 59.3$m16658$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m16659$nota-0283$m16659$, $m16660$nota-0033$m16660$, $m16661$complementa$m16661$, $m16662$dado de referência de composição corporal de ciclistas profissionais, útil como benchmark para razão potência/peso$m16662$)
