INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16667$nota-0289$m16667$, $m16668$Exercise Physiology McArdle.pdf$m16668$, $m16669$858$m16669$, $m16670$Nine to 12 mo of endurance training increased VO2max by 19% in men and 22% in women (Table 31.1). These values represent the high end of improvement typically observed for younger adults.$m16670$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16671$nota-0289$m16671$, $m16672$Exercise Physiology McArdle.pdf$m16672$, $m16673$858$m16673$, $m16674$For men, improved aerobic power was associated with a 15% larger maximum stroke volume (corresponding cardiac output increase represented two thirds of the VO2max increase) and 7% greater maximum a-vO2 difference... For the women, the a-vO2 difference explained the total VO2max increase, with no change in left-ventricular performance at maximal exercise.$m16674$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m16675$nota-0289$m16675$, $m16676$nota-0207$m16676$, $m16677$complementa$m16677$, $m16678$nota-0207 trata do declínio linear do VO2máx com a idade; esta nota mostra que, apesar do declínio de base, idosos ainda respondem fortemente ao treino de endurance$m16678$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m16679$nota-0289$m16679$, $m16680$nota-0216$m16680$, $m16681$complementa$m16681$, $m16682$reforça, com dado específico de idosos, que a capacidade de resposta ao treino de VO2máx não desaparece com a idade quando o estímulo é adequado$m16682$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16683$nota-0068$m16683$, $m16684$Training and Racing with a Power Meter.pdf$m16684$, $m16685$176$m16685$, $m16686$the maximum force that this individual could produce when pedaling was just over 1,100 newtons (N)... But the highest force the athlete ever generated (had to generate) when racing (e.g., when sprinting) was only about 600 N (i.e., only about 55 percent of maximal force), and during the vast majority of the time the athlete was applying less than 400 N (i.e., only about 35 percent of maximal force).$m16686$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16687$nota-0068$m16687$, $m16688$Training and Racing with a Power Meter.pdf$m16688$, $m16689$177$m16689$, $m16690$even time trialing at FTP required that the athlete repeatedly press on the pedals with only about 25 percent of the maximal force he or she could produce.$m16690$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m16691$nota-0068$m16691$, $m16692$nota-0067$m16692$, $m16693$complementa$m16693$, $m16694$usa a mesma metodologia AEPF/CPV da Quadrant Analysis (nota-0067) para comparar força real usada com força máxima$m16694$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16695$nota-0074$m16695$, $m16696$Training and Racing with a Power Meter.pdf$m16696$, $m16697$167$m16697$, $m16698$The Type I fibers are maximally recruited even at a relatively low exercise intensity (i.e., 40 percent of VO2max), whereas the Type IIa and especially Type IIx fibers are recruited, only at much higher exercise intensities.$m16698$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16699$nota-0074$m16699$, $m16700$Training and Racing with a Power Meter.pdf$m16700$, $m16701$167$m16701$, $m16702$functional threshold power appears to occur at the power (and thus force) at which significant fast-twitch fiber recruitment first begins.$m16702$);
